public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    return graph.getVertex2VertexMap()
                .entrySet()
                .stream()
                .collect(Collectors.toMap(
                        entry -> entry.getKey(),
                        entry -> entry.getValue()));
}

// Perform some sanity checks on the input
if (graph == null) {
    throw new IllegalArgumentException("Input graph cannot be null");
}

// Create a new mapping object
IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>();

// Iterate over all vertices in the graph
for (V vertex : graph.getVertices()) {
    // Add a vertex to the mapping with itself as the target
    mapping.addVertex(vertex, vertex);
}

// Iterate over all edges in the graph
for (E edge : graph.getEdges()) {
    // Get the source and target vertices of the edge
    V source = graph.getSourceVertex(edge);
    V target = graph.getTargetVertex(edge);

    // Add an edge to the mapping with the source and target vertices
    mapping.addEdge(source, target, edge);
}

return mapping;

public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    return new IsomorphicGraphMapping<V, E>() {
        @Override
        public Graph<V, E> apply(Graph<V, E> graph) {
            Graph<V, E> result = new Graph<>();
            for (V v : graph.getVertices()) {
                result.addVertex(v);
            }
            for (E e : graph.getEdges()) {
                result.addEdge(e.getStartVertex(), e.getEndVertex(), e);
            }
            return result;
        }
    };
}

