这个方法将计算一个图的自映射(图自映射是映射图中每个顶点到自身)。

首先，我们检查参数 graph 是否为 null，如果是，则引发 IllegalArgumentException 以指示该参数无效。

接下来，我们创建一个 IsomorphicGraphMapping 对象并初始化它以便将所需的内容映射到它的内部 Map 对象中。

然后，我们遍历图中的所有顶点和边，将每个顶点映射到它自身，并将每个边映射到它自身。

最后，我们返回由 IsomorphicGraphMapping 对象表示的映射。

我们期望这个方法总是返回一个有效且有意义的映射，而不是 null 或其他无效值。

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }

    if (!file.exists()) {
        return;
    }

    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File child : files) {
                forceDeleteOnExit(child);
            }
        }
    }

    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file cannot be null");
    }
    if (file.isDirectory()) {
        file.delete();
        File[] files = file.listFiles();
        if (files != null) {
            for (File f : files) {
                forceDeleteOnExit(f);
            }
        }
    } else {
        file.deleteOnExit();
    }
}

public static void forceDeleteOnExit(File file) throws IOException {

    if (file == null) {
        throw new NullPointerException("File must not be null");
    }

    if (file.exists()) {
        if (file.isDirectory()) {
            deleteDirectory(file);
        } else {
            file.deleteOnExit();
        }
    } else {
        throw new IOException("File does not exist: " + file);
    }
}

private static void deleteDirectory(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }

    if (!directory.isDirectory()) {
        throw new IOException("Not a directory: " + directory);
    }

    File[] files = directory.listFiles();
    if (files == null) { // null if security restricted
        throw new IOException("Failed to list contents of " + directory);
    }

    for (File file : files) {
        forceDeleteOnExit(file);
    }

    directory.deleteOnExit();
}

/** 
 * Schedules a file to be deleted when JVM exits. If file is directory delete it and all sub-directories.
 * @param file  file or directory to delete, must not be {@code null}
 * @throws NullPointerException if the file is {@code null}
 * @throws IOException in case deletion is unsuccessful
 */
public static void forceDeleteOnExit(File file) throws IOException {
    if (file.isFile()) {
        file.deleteOnExit();
    } else if (file.isDirectory()) {
        file.listFiles().forEach(forceDeleteOnExit);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }

    // Delete the file if it is not a directory
    if (!file.isDirectory()) {
        if (!file.delete()) {
            throw new IOException("Failed to delete file: " + file.getAbsolutePath());
        }
    } else {
        // Delete the directory and all sub-directories
        deleteDirectory(file);
    }
}

// Helper method to delete a directory and all its sub-directories
private static void deleteDirectory(File directory) throws IOException {
    // First, delete all files in the directory
    for (File file : directory.listFiles()) {
        if (file.isDirectory()) {
            deleteDirectory(file);
        } else {
            if (!file.delete()) {
                throw new IOException("Failed to delete file: " + file.getAbsolutePath());
            }
        }
    }

    // Then, delete the directory itself if it is not a drive root
    if (!directory.getAbsolutePath().equals(File.listRoots()[0].getAbsolutePath())) {
        if (!directory.delete()) {
            throw new IOException("Failed to delete directory: " + directory.getAbsolutePath());
        }
    }
}

