public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();

    // Skip leading slash if absolute path
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }

    // Split path into segments
    String[] segments = path.split("/");

    // Decode segments if necessary
    if (decode) {
        for (int i = 0; i < segments.length; i++) {
            segments[i] = URLDecoder.decode(segments[i], StandardCharsets.UTF_8);
        }
    }

    // Convert to PathSegmentImpl instances
    for (String segment : segments) {
        pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
}

/**
 * Decode an URI path component into a list of path segments.
 *
 * @param u the URI
 * @param decode if true, the path segments are decoded
 * @return the list of path segments
 */
public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    // Check if the URI is null
    if (u == null) {
        return pathSegments;
    }

    try {
        // Get the path component of the URI
        String path = u.getPath();
        // Check if the path is null or empty
        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        // Split the path component into path segments
        String[] segments = path.split("/");
        // Iterate over the path segments and add them to the list
        for (String segment : segments) {
            // Check if the segment is null or empty
            if (segment != null && !segment.isEmpty()) {
                if (decode) {
                    // Decode the segment and add it to the list
                    pathSegments.add(new PathSegmentImpl(URLDecoder.decode(segment, "UTF-8")));
                } else {
                    // Add the segment as is to the list
                    pathSegments.add(new PathSegmentImpl(segment));
                }
            }
        }

        return pathSegments;
    } catch (Exception e) {
        // log the exception and return an empty list
        System.err.println("Error decoding URI path: " + e.getMessage());
        return pathSegments;
    }
}

