public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Check if the path component is empty
    if (u.getPath() == null || u.getPath().isEmpty()) {
        return pathSegments;
    }

    // Decode the path component if requested
    if (decode) {
        try {
            u = new URI(u.getScheme(), u.getHost(), u.getPath(), u.getQuery(), u.getFragment());
        } catch (URISyntaxException e) {
            // Ignore, just use the original URI
        }
    }

    // Split the path component into segments
    String[] segments = u.getPath().split("/");

    // Add each segment to the list of path segments
    for (String segment : segments) {
        if (segment == null || segment.isEmpty()) {
            continue;
        }
        PathSegmentImpl pathSegment = new PathSegmentImpl(segment);
        pathSegments.add(pathSegment);
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
