        // If the descriptor starts with 'L', it means we need to pop an object reference
        popObject();
    } else if (descriptor.charAt(0) == '[') {
        // If the descriptor starts with '[', it means we need to pop an array reference
        popArray();
    } else if (descriptor.charAt(0) == 'V') {
        // If the descriptor starts with 'V', it means we need to pop a void value
        // In this case, there is nothing to do since void values don't have references
    } else {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

