public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    float width = box.getWidth() / 2;
    Box2D left = new Box2D(box.getPosition().x, box.getPosition().y, width, box.getHeight());
    Box2D right = new Box2D(box.getPosition().x + width, box.getPosition().y, width, box.getHeight());
    return new Pair(left, right);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {

    // Calculate the center of the box along the x axis
    double centerX = box.getX() + box.getWidth() / 2;

    // Create two new boxes, one centered around the centerX point
    Box2D leftBox = new Box2D(centerX - box.getWidth() / 4, box.getY(), box.getWidth() / 2, box.getHeight());
    Box2D rightBox = new Box2D(centerX + box.getWidth() / 4, box.getY(), box.getWidth() / 2, box.getHeight());

    // Return the pair of boxes
    return new Pair<Box2D, Box2D>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // Validation
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null.");
    }

    // Calculate the center of the box
    Point2D center = box.getCenter();

    // Calculate the half-width of the box
    double halfWidth = box.getWidth() / 2.0;

    // Calculate the top half box
    Box2D topHalfBox = new Box2D(center.getX() - halfWidth, center.getY(), halfWidth, box.getHeight());

    // Calculate the bottom half box
    Box2D bottomHalfBox = new Box2D(center.getX() + halfWidth, center.getY(), halfWidth, box.getHeight());

    // Return a pair with the two resulting boxes
    return new Pair<>(topHalfBox, bottomHalfBox);
}

