 * @param size The number of additional bytes that the vector should be able to receive.
 */
private void enlarge(final int size) {
    // Calculate the new capacity
    final int newCapacity = this.capacity + size;

    // Check if the new capacity is greater than the maximum capacity
    if (newCapacity > this.MAX_CAPACITY) {
        // Throw a RuntimeException if the new capacity is greater than the maximum capacity
        throw new RuntimeException("Cannot enlarge the vector beyond its maximum capacity.");
    }

    // Create a new byte array with the new capacity
    final byte[] newBytes = new byte[newCapacity];

    // Copy the old bytes into the new array
    System.arraycopy(this.bytes, 0, newBytes, 0, this.size);

    // Set the new bytes array
    this.bytes = newBytes;

    // Increase the capacity
    this.capacity = newCapacity;
}

