public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalContentSize = 0;

    // Write the contents of the buffer to the output stream
    ByteBuffer buffer = node.getByteBuffer();
    while (buffer.hasRemaining()) {
        int bytesWritten = out.write(buffer);
        totalContentSize += bytesWritten;
    }

    // If the buffer is still not fully written, write the remaining bytes to the output stream
    if (buffer.hasRemaining()) {
        int remainingBytes = buffer.remaining();
        byte[] remainingBuffer = new byte[remainingBytes];
        buffer.get(remainingBuffer, 0, remainingBytes);
        out.write(remainingBuffer);
        totalContentSize += remainingBytes;
    }

    // Return the total content size of the buffer
    return totalContentSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // Write the node's value
        out.writeUTF(node.value);
        totalSize += node.value.length();
        // Write the node's next pointer
        out.writeUTF(node.next == null ? null : node.next.value);
        totalSize += (node.next == null ? 0 : node.next.value.length());
        node = node.next;
    }
    return totalSize;
}

