// This method computes the floor of the binary logarithm of the given number, i.e., the base 2 logarithm of the number rounded down to the nearest integer.

public int computeBinaryLog(int n) {
    // Check if the input is a negative number, which is invalid.
    if (n < 0) {
        throw new IllegalArgumentException("The input cannot be a negative number.");
    }

    // Initialize the result with 0.
    int result = 0;

    // While the input is greater than 0, keep dividing it by 2 and incrementing the result.
    while (n > 0) {
        n = n / 2;
        result++;
    }

    // Return the result.
    return result;
}

/**
 * Computes floor($\log_2 (n)$) $+ 1$
 */
private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int result = 0;
    while (n > 1) {
        n >>= 1;
        result++;
    }
    return result;
}

/** 
 * Computes floor($\log_2 (n)$) $+ 1$
 */
public int computeBinaryLog(int n){
    if(n <= 0){
        throw new IllegalArgumentException("Argument 'n' must be a positive integer");
    }
    int log = 0;
    while(n > 0){
        log++;
        n >>= 1;
    }
    return log;
}

/**
 * Computes floor($\log_2 (n)$) $+ 1$
 */
private int computeBinaryLog(int n) {
    // Check if n is a power of 2
    if (n == 1) {
        return 0;
    }

    // Compute floor($\log_2 (n)$)
    int log = 0;
    while (n > 1) {
        n = n / 2;
        log++;
    }

    // Add 1 to get the ceiling
    return log + 1;
}

