        appenders.remove(name);
    }
}

public interface LogAppender {
    void append(String message);
}

class ConsoleAppender implements LogAppender {
    @Override
    public void append(String message) {
        System.out.println(message);
    }
}

class FileAppender implements LogAppender {
    private final String filename;

    public FileAppender(String filename) {
        this.filename = filename;
    }

    @Override
    public void append(String message) {
        try (FileWriter fileWriter = new FileWriter(filename, true)) {
            fileWriter.write(message + System.lineSeparator());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

class DatabaseAppender implements LogAppender {
    private final Connection connection;

    public DatabaseAppender(Connection connection) {
        this.connection = connection;
    }

    @Override
    public void append(String message) {
        try (PreparedStatement statement = connection.prepareStatement("INSERT INTO logs (log_entry) VALUES (?)")) {
            statement.setString(1, message);
            statement.executeUpdate();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

