protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    List<V> vertices = new ArrayList<>();
    Iterator<E> edges = tour.iterator();
    vertices.add(edges.next().getSource());

    while (edges.hasNext()) {
        E edge = edges.next();
        if (edge.getSource().equals(vertices.get(vertices.size() - 1))) {
            vertices.add(edge.getDestination());
        } else {
            vertices.add(edge.getSource());
        }
    }

    return graph.getPath(vertices);
}

private GraphPath<V, E> convertSetToGraphPath(Set<E> tour, Graph<V, E> graph) {
    // Validate input
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("The tour set must not be empty.");
    }

    // Initialize the graph path
    GraphPath<V, E> path = new GraphPathImpl<>(graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the source and destination vertices of the edge
        V source = graph.getEdgeSource(edge);
        V destination = graph.getEdgeDest(edge);

        // Add the edge to the graph path
        path.addEdge(edge);

        // Add the source vertex to the graph path, if it does not already exist
        if (!path.containsVertex(source)) {
            path.addVertex(source);
        }

        // Add the destination vertex to the graph path, if it does not already exist
        if (!path.containsVertex(destination)) {
            path.addVertex(destination);
        }
    }

    // Return the completed graph path
    return path;
}

