    // 1. Move all vertices from the bucket with the minimum label to the bucket with label 0
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (i == minLabel) {
            for (int vertex : bucketsByLabel.get(i)) {
                bucketsByLabel.get(0).add(vertex);
            }
            bucketsByLabel.get(i).clear();
        }
    }

    // 2. Update the labels accordingly
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (i < minLabel) {
            for (int vertex : bucketsByLabel.get(i)) {
