@Override
protected Integer provideNextVertex() {
    // If the queue is empty, return null
    if (this.queue.isEmpty()) {
        return null;
    }

    // Get the next vertex from the queue
    Integer vertex = this.queue.poll();

    // Check if the vertex has been visited before
    if (this.visitedVertices.contains(vertex)) {
        // If it has, skip it
        return this.provideNextVertex();
    }

    // Mark the vertex as visited
    this.visitedVertices.add(vertex);

    // Return the next vertex
    return vertex;
}

