@Override
protected V provideNextVertex() {
    if (queue.isEmpty()) {
        // If the queue is empty, return null
        return null;
    }

    // Get the next vertex from the queue
    V vertex = queue.poll();

    // If the vertex is not marked as discovered, mark it as discovered
    // and add its neighbors to the queue
    if (!vertex.isDiscovered()) {
        vertex.setDiscovered(true);
        for (V neighbor : vertex.getNeighbors()) {
            if (!neighbor.isDiscovered()) {
                queue.add(neighbor);
            }
        }
    }

    return vertex;
}

