  // 2. Add the current vertex to the visited set
  visited.add(this.currentVertex);
  // 3. If the current vertex has no neighbors, return null
  if (this.currentVertex.getNeighbors().isEmpty()) {
    return null;
  }
  // 4. Return a random neighbor of the current vertex that has not yet been processed
  List<V> unvisitedNeighbors = getUnvisitedNeighbors(this.currentVertex);
  V randomNeighbor = unvisitedNeighbors.get(ThreadLocalRandom.current().nextInt(unvisitedNeighbors.size()));
  return randomNeighbor;
}

