private List<V> getUnvisitedNeighbors(V vertex) {
  List<V> unvisitedNeighbors = new ArrayList<>();
  for (E edge : vertex.getNeighbors()) {
    if (!visited.contains(edge.getDestination())) {
      unvisitedNeighbors.add(edge.getDestination());
    }
  }
  return unvisitedNeighbors;
}

