 * Removes the non-null {@code node} from the list.
 */
private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> current = head;
    ListNodeImpl<E> previous = null;

    while (current != null) {
        if (current == node) {
            if (previous == null) {
                head = head.next;
            } else {
                previous.next = current.next;
            }
            current.next = null;
            size--;
            return true;
        }
        previous = current;
        current = current.next;
    }

    return false;
}

