        }

        // Step 2: Calculate the number of bytes required to represent the int
        int bytesRequired = (intValue.numberOfLeadingZeros() + 7) / 8;

        // Step 3: Grow the byte vector if necessary
        if (bytesRequired > capacity()) {
            grow(bytesRequired);
        }

        // Step 4: Convert the int to bytes and put it into the vector
        int mask = 0xff;
        for (int i = 0; i < bytesRequired; i++) {
            put((byte) ((intValue >> (8 * i)) & mask));
        }

        // Step 5: Return this byte vector
        return this;
    }

