 */
public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Check if the type variable has a bound
    if (typeVariable.getBounds() != null && !typeVariable.getBounds().isEmpty()) {
        // Return the first bound
        return typeVariable.getBounds().iterator().next();
    } else {
        // Default to Unknown.class if no bound can be resolved
        return Unknown.class;
    }
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check preconditions
    if (graph == null || vertices == null || vertices.size() == 0) {
        throw new IllegalArgumentException("Invalid input argument");
    }

    // Construct the subgraph
    Graph<V, E> subgraph = createSubgraph(graph, vertices);

    // Check if the subgraph is connected
    if (subgraph.getNumComponents() != 1) {
        return false;
    }

    // Check if the subgraph is a clique
    Set<V> neighbors = new HashSet<>();
    for (V vertex : vertices) {
        neighbors.addAll(subgraph.getNeighbors(vertex));
    }
    return neighbors.containsAll(vertices);
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.size() == 0) {
        return false;
    }

    // check if the vertex set forms a complete subgraph
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

/**
 * Check whether the subgraph of 'graph' induced by 'vertices' is complete, i.e. a clique.
 * @param graph the graph
 * @param vertices the vertices to induce the subgraph from
 * @return true if the induced subgraph is a clique
 */
private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // check if all vertices in 'vertices' are in 'graph'
    if (!graph.containsAllVertices(vertices)) {
        throw new IllegalArgumentException("Some vertices in 'vertices' are not in 'graph'");
    }

    // check if 'graph' is connected
    if (!graph.isConnected()) {
        throw new IllegalArgumentException("'graph' is not connected");
    }

    // check if 'vertices' is a subgraph of 'graph'
    if (!graph.containsSubgraph(vertices)) {
        throw new IllegalArgumentException("'vertices' is not a subgraph of 'graph'");
    }

    // check if 'vertices' is complete
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

