private void popType() {
    // Check if there are any elements in the output frame stack
    if (outputFrameStack.isEmpty()) {
        throw new IllegalStateException("Attempted to pop type from empty output frame stack");
    }

    // Pop the top element from the output frame stack
    outputFrameStack.pop();
}

/**
 * Pops the argument types for a method descriptor from the output frame stack.
 *
 * @param descriptor a method descriptor.
 */
private void popType(String descriptor) {
    // Check if the descriptor is a method descriptor
    if (!descriptor.startsWith("(") || !descriptor.endsWith(")")) {
        throw new IllegalArgumentException("Not a method descriptor: " + descriptor);
    }

    // Pop the argument types for the method descriptor
    String argumentTypes = descriptor.substring(1, descriptor.length() - 1);
    for (String argumentType : argumentTypes.split(" ")) {
        popType(argumentType);
    }
}

/**
* Pops as many abstract types from the output frame stack as described by the given descriptor.
* @param descriptor a type or method descriptor (in which case its argument types are popped).
*/
private void pop(final String descriptor) {
    // Check if the given descriptor is a method descriptor
    if (descriptor.contains("(")) {
        // Pop the argument types from the output frame stack
        String[] argTypes = descriptor.substring(1, descriptor.indexOf("(")).split(";");
        for (String argType : argTypes) {
            // Pop the argument type from the output frame stack
            pop(argType);
        }
    } else {
        // Pop a single abstract type from the output frame stack
        pop(descriptor);
    }
}

