 * Finds a minimum lower bound for every key.
 * @param keys a list of keys.
 * @return the computed key upper bound.
 */
public List<Integer> computeUpperBounds(List<K> keys) {
    // Step 1: Initialize an empty hash table
    Map<K, Integer> upperBounds = new HashMap<>();

    // Step 2: Iterate over the input keys and compute the maximum value for each key
    for (K key : keys) {
        // If the current key is not in the hash table, add it with a value of 0
        if (!upperBounds.containsKey(key)) {
            upperBounds.put(key, 0);
        }

        // Get the current maximum value for the key
        int currentMax = upperBounds.get(key);

        // If the current key has a higher maximum value than 0, update the hash table
        if (currentMax > 0) {
            upperBounds.put(key, currentMax + 1);
        }
    }

    // Step 3: Return the computed key upper bounds
    return new ArrayList<>(upperBounds.values());
}

