    Finds a minimum lower bound for every key.
    :param keys: a list of keys.
    :return: the computed key upper bound.
    """
    # Initialize the upper bounds for each key as the key itself
    upper_bounds = {key: key for key in keys}

    # Iterate over the keys in descending order
    for key in sorted(keys, reverse=True):
        # If the key has not been processed, continue
        if upper_bounds[key] == key:
            continue

        # Find the closest key that has not been processed
        closest_key = None
        for j in range(len(keys)):
            if keys[j] < key and upper_bounds[keys[j]] != keys[j]:
