public static String applyRelativePath(String path, String relativePath) {
    // Check if the path is null or empty
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path cannot be null or empty");
    }

    // Check if the relative path is null or empty
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Relative path cannot be null or empty");
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");

    // Split the relative path into its components
    String[] relativePathComponents = relativePath.split("/");

    // Create a new string builder to build the result path
    StringBuilder resultPath = new StringBuilder();

    // Loop through the relative path components
    for (int i = 0; i < relativePathComponents.length; i++) {
        // If the current component is "..", remove the last component from the result path
        if (relativePathComponents[i].equals("..")) {
            if (resultPath.length() > 0) {
                resultPath.delete(resultPath.lastIndexOf("/") + 1, resultPath.length());
            }
        }
        // Otherwise, append the current component to the result path
        else {
            resultPath.append(relativePathComponents[i]);
            // If this is not the last component, append a "/" separator
            if (i < relativePathComponents.length - 1) {
                resultPath.append("/");
            }
        }
    }

    // If the result path is empty, return the root path ("/")
    if (resultPath.length() == 0) {
        return "/";
    }

    // Otherwise, return the result path
    return resultPath.toString();
}

/**
 * Apply the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
 * @param path the path to start from (usually a full file path)
 * @param relativePath the relative path to apply(relative to the full file path above)
 * @return the full file path that results from applying the relative path
 */
public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    if (relativePath.isEmpty()) {
        return path;
    }

    if (!path.endsWith(File.separator)) {
        path += File.separator;
    }

    String[] parts = relativePath.split(File.separator);
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        path += part;
        path += File.separator;
    }

    return path.substring(0, path.length() - 1);
}

