public int readTag() throws IOException {
    int tag = 0;
    int ch = reader.read();
    while (ch != -1 && (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r')) {
        ch = reader.read();
    }
    if (ch == -1) {
        return 0;
    }
    if (ch >= '0' && ch <= '9') {
        do {
            tag = (tag << 3) + (tag << 1) + (ch - '0');
            ch = reader.read();
        } while (ch != -1 && (ch >= '0' && ch <= '9'));
    }
    reader.unread(ch);
    return tag;
}

