public string BuildContentRange()
{
    string contentRange = "";

    // Check if the Content-Range header is present in the current response
    if (Response.Headers.ContainsKey("Content-Range"))
    {
        // Get the current Content-Range value
        string currentContentRange = Response.Headers["Content-Range"];

        // Split the value into parts using '/' as a delimiter
        string[] parts = currentContentRange.Split('/');

        // Check if the value is in the expected format
        if (parts.Length == 2 && !string.IsNullOrEmpty(parts[0]) && !string.IsNullOrEmpty(parts[1]))
        {
            // Get the start and end values of the range
            string start = parts[0];
            string end = parts[1];

            // Check if the start value is a valid integer
            if (int.TryParse(start, out int startInt))
            {
                // Check if the end value is a valid integer
                if (int.TryParse(end, out int endInt))
                {
                    // Calculate the total number of bytes in the range
                    int totalBytes = endInt - startInt + 1;

                    // Build the Content-Range value
                    contentRange = $"{start}-{end}/{totalBytes}";
                }
                else
                {
                    throw new ArgumentException("Invalid end value in Content-Range header.", "end");
                }
            }
            else
            {
                throw new ArgumentException("Invalid start value in Content-Range header.", "start");
            }
        }
        else
        {
            throw new ArgumentException("Invalid Content-Range header value.", "contentRange");
        }
    }
    else
    {
        throw new InvalidOperationException("Content-Range header is missing.");
    }

    return contentRange;
}

